CREATE TABLE IF NOT EXISTS `market_data_sources` (`id` text PRIMARY KEY NOT NULL, `source` text NOT NULL, `confidence` text NOT NULL, `source_file` text DEFAULT '' NOT NULL, `imported_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL, `metadata` text DEFAULT '{}' NOT NULL);
CREATE TABLE IF NOT EXISTS `market_categories` (`subject_id` text PRIMARY KEY NOT NULL, `name_ru` text NOT NULL, `name_zh` text DEFAULT '' NOT NULL, `parent_id` text DEFAULT '' NOT NULL, `parent_name` text DEFAULT '' NOT NULL, `level` integer DEFAULT 1 NOT NULL, `updated_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE TABLE IF NOT EXISTS `market_category_metrics` (`subject_id` text NOT NULL, `period_days` integer NOT NULL, `metric_date` text NOT NULL, `source_id` text NOT NULL, `metrics` text DEFAULT '{}' NOT NULL, `updated_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL, CONSTRAINT `market_category_metrics_pk` PRIMARY KEY(`subject_id`,`period_days`,`metric_date`,`source_id`));
CREATE TABLE IF NOT EXISTS `market_category_history` (`subject_id` text NOT NULL, `period_days` integer NOT NULL, `metric_date` text NOT NULL, `source_id` text NOT NULL, `metrics` text DEFAULT '{}' NOT NULL, CONSTRAINT `market_category_history_pk` PRIMARY KEY(`subject_id`,`period_days`,`metric_date`,`source_id`));
CREATE TABLE IF NOT EXISTS `market_products` (`subject_id` text NOT NULL, `nm_id` integer NOT NULL, `source_id` text NOT NULL, `payload` text DEFAULT '{}' NOT NULL, `updated_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL, CONSTRAINT `market_products_pk` PRIMARY KEY(`subject_id`,`nm_id`,`source_id`));
CREATE TABLE IF NOT EXISTS `market_sellers` (`subject_id` text NOT NULL, `seller_id` text NOT NULL, `source_id` text NOT NULL, `payload` text DEFAULT '{}' NOT NULL, `updated_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL, CONSTRAINT `market_sellers_pk` PRIMARY KEY(`subject_id`,`seller_id`,`source_id`));
CREATE TABLE IF NOT EXISTS `market_watchlist` (`subject_id` text PRIMARY KEY NOT NULL, `created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL, `note` text DEFAULT '' NOT NULL);
CREATE INDEX IF NOT EXISTS `market_metrics_period_date_idx` ON `market_category_metrics` (`period_days`,`metric_date`);
CREATE INDEX IF NOT EXISTS `market_history_subject_date_idx` ON `market_category_history` (`subject_id`,`metric_date`);
